<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include <cstdio>
#include <queue>
#include <cmath>
#include <algorithm>
#include <cstring>
#define fr(i,a,b) for(int i=a;i<b;i++)
#define rep(i,b) fr(i,0,b)
#define mp make_pair
#define X first
#define Y second
#define oo 10000000

using namespace std;
typedef pair<int,int> pii;
#define N 300
#define M 900000
#define mp make_pair
#define F first
#define S second
pii q[N];
int level[N], adj[N], copy_adj[N], fila[N];
int to[M], ant[M], cap[M], pa;
int n,t;
int dx[] = {-1,0,1,0};
int dy[] = {0,1,0,-1};
void add(int f, int t, int c){
    to[pa] = t, cap[pa] = c, ant[pa] = adj[f]; adj[f] = pa; pa++;
    swap(f,t);
    c = 0;
    to[pa] = t, cap[pa] = c, ant[pa] = adj[f]; adj[f] = pa; pa++;
}



int bfs(int source, int sink){
    memset(level, -1, sizeof level);
    level[source] = 0;
    int pos = 0, tam = 0;
    fila[tam++] = source;
    while(pos < tam){
        int now = fila[pos++];
        for(int i = adj[now]; i >= 0; i = ant[i]){
            if(cap[i] && level[to[i]] == -1){
                level[to[i]] = level[now]+1;
                fila[tam++] = to[i];
            }
        }
    }
    return level[sink] != -1;
}

int dfs(int no, int sink, int flow){
    if(no == sink) return flow;
    for(int &i = copy_adj[no]; i >= 0; i = ant[i]){
        if(cap[i] && level[no] + 1 == level[to[i]]){
            int nflow = dfs(to[i], sink, min(flow, cap[i]));
            if(nflow){
                cap[i] -= nflow; cap[i^1] += nflow;
                return nflow;
            }
        }
    }
    return 0;
}



int maxflow(int source, int sink){
    int mf = 0;
    while(true){
        if(bfs(source, sink)){
            memcpy(copy_adj, adj, sizeof adj);
            while(true){
                int add = dfs(source, sink, 1<<30);
                if(add) mf += add;
                else break;
            }
        }
        else break;
    }
    return mf;
}



bool valid(int a, int b){
    return a >= 0 && a < n && b >= 0 && b < n;
}


int inds[21][21];
int inds2[21][21];
int mk[21][21];
char gr[21][21];
char gr2[21][21];
int c[21][21];
int in;
int S, T;


int rp, cp;

void busc(int a, int b){
    int ini = 0, fim = 0;
    memset(mk, 0, sizeof mk);
    memset(c, -1, sizeof c);
    fr(i,0,n) fr(j,0,n) if(gr[i][j] == 'Y') mk[i][j] = 1;
    q[fim++] = mp(rp,cp);
    q[fim++] = mp(a,b);
    c[a][b] = c[rp][cp] = 0;
    mk[a][b] = 1;
    mk[rp][cp] = 2;
    while(ini < fim){
        pii now = q[ini++];
        if(mk[now.F][now.S] == 1 && gr2[now.F][now.S] > '0' && gr2[now.F][now.S] <= '9'){
            add(inds[a][b], inds2[now.F][now.S], 9);
        }
        if(mk[now.F][now.S] == 1 && c[now.F][now.S] == t){
            continue;
        }
        fr(i,0,4){
            int nx = now.F + dx[i], ny = now.S + dy[i];
            if(valid(nx,ny) && mk[nx][ny] == 0){
                mk[nx][ny] = mk[now.F][now.S];
                c[nx][ny] = c[now.F][now.S] + 1;
                q[fim++] = mp(nx,ny);
            }
            else if(mk[now.F][now.S] == 1 && valid(nx, ny) && mk[nx][ny] == 2 && c[nx][ny] == c[now.F][now.S] + 1 && gr2[nx][ny] > '0' && gr2[nx][ny] <= '9'){
                add(inds[a][b], inds2[nx][ny], 9);
            }
        }
    }
}













int main(){
    scanf("%d %d",&n,&t);
    S = 202, T = 203;
    memset(adj, -1, sizeof adj);
    pa = 0;
    in = 0;
    memset(inds, -1, sizeof inds);
    memset(inds2, -1, sizeof inds2);
    fr(i,0,n){ 
        scanf("%s",gr[i]);
        fr(j,0,n){
            if(gr[i][j] > '0' && gr[i][j] <= '9'){ 
                add(S, in, gr[i][j]-'0');
                inds[i][j] = in++;
            }
            if(gr[i][j] == 'Z') rp = i, cp = j;
        }
    }
    fr(i,0,n){ 
        scanf("%s",gr2[i]);
        fr(j,0,n){
            if(gr2[i][j] > '0' && gr2[i][j] <= '9'){
                add(in, T, gr2[i][j]-'0');
                inds2[i][j] = in++;
            }
        }
    }
    fr(i,0,n){
        fr(j,0,n){
            if(gr[i][j] > '0' && gr[i][j] <= '9' && gr2[i][j] > '0' && gr2[i][j] <= '9') add(inds[i][j], inds2[i][j], 9);
            if(gr[i][j] > '0' && gr[i][j] <= '9') busc(i,j);
        }
    }
    printf("%d\n",maxflow(S,T));
    return 0;
}






























